// ABOUT TAB
const items = document.querySelectorAll('.page-item');
const aboutTab = document.querySelector('.tab-section .page-field');

// Eğer bir item seçiliğinde aboutTab'in boyutunu değiştirmek istiyorsanız:
function toggleAboutTabSize() {
    aboutTab.classList.add('!h-[100px]');
}

items.forEach(item => {
    const scrollTargetSelector = item.getAttribute('data-scrollable');
    const scrollTarget = document.querySelector(scrollTargetSelector);

    if (scrollTarget) {
        const scrollTrigger = scrollTarget.offsetTop - 200;

        function setActiveItem() {
            items.forEach(item => {
                item.classList.remove('is-active');
            });
            item.classList.add('is-active');
        }

        function checkScrollPosition() {
            if (window.pageYOffset > scrollTrigger) {
                setActiveItem();
            }
            // Eğer scroll hedefi en üste ulaştığında 'aboutTab' elemanındaki sınıfı kaldırmak istiyorsanız:
            if (window.pageYOffset === 0) {
                aboutTab.classList.remove('!h-[100px]');
            }
        }

        window.addEventListener('scroll', checkScrollPosition);

        // Eğer item'a tıklandığında aboutTab'in boyutunu değiştirmek istiyorsanız:
        item.addEventListener('click', toggleAboutTabSize);
    }
});



// MAP ZOOM CONTROL
let mapWrappers = document.querySelectorAll('.map-wrapper');

mapWrappers.forEach(function (mapWrapper) {
    let zoomIn = mapWrapper.querySelector('.zoom-in');
    let zoomOut = mapWrapper.querySelector('.zoom-out');
    let mapField = mapWrapper.querySelector('.map-image-field');
    let scale = 1;
    let zoomInCount = 0;
    let isDragging = false;
    let startX;
    let startY;
    let translateX = 0;
    let translateY = 0;

    function updateTransform() {
        mapField.style.transform = `scale(${scale}) translate(${translateX}px, ${translateY}px)`;
    }

    // --- Zoom In ---
    zoomIn.addEventListener('click', function () {
        if (zoomInCount < 5) {
            scale *= 1.5;
            updateTransform();
            mapField.style.transition = 'transform 0.5s';
            setTimeout(() => {
                mapField.style.transition = 'none';
            }, 500);
            zoomInCount++;
        }
        if (zoomInCount > 0) mapField.style.cursor = 'grab';
    });

    // --- Zoom Out ---
    zoomOut.addEventListener('click', function () {
        if (scale > 1) {
            scale /= 1.5;
            if (scale <= 1) {
                scale = 1;
                translateX = 0;
                translateY = 0;
            }
            updateTransform();
            mapField.style.transition = 'transform 0.5s';
            setTimeout(() => {
                mapField.style.transition = 'none';
            }, 500);
            zoomInCount = Math.max(zoomInCount - 1, 0);
        }
        if (zoomInCount === 0) mapField.style.cursor = 'default';
    });

    // --- Drag (Desktop) ---
    mapField.addEventListener('mousedown', (e) => {
        if (zoomInCount > 0) {
            isDragging = true;
            startX = e.clientX;
            startY = e.clientY;
            mapField.style.cursor = 'grabbing';
        }
    });

    document.addEventListener('mouseup', () => {
        isDragging = false;
        if (zoomInCount > 0) mapField.style.cursor = 'grab';
    });

    document.addEventListener('mousemove', (e) => {
        if (isDragging) {
            let newX = e.clientX;
            let newY = e.clientY;
            translateX += newX - startX;
            translateY += newY - startY;
            updateTransform();
            startX = newX;
            startY = newY;
        }
    });

    // --- Drag (Mobile Touch) ---
    mapField.addEventListener('touchstart', (e) => {
        if (zoomInCount > 0 && e.touches.length === 1) {
            isDragging = true;
            startX = e.touches[0].clientX;
            startY = e.touches[0].clientY;
        }
    });

    mapField.addEventListener('touchmove', (e) => {
        if (isDragging && e.touches.length === 1) {
            e.preventDefault(); // Sayfanın kaymasını engeller
            let newX = e.touches[0].clientX;
            let newY = e.touches[0].clientY;
            translateX += newX - startX;
            translateY += newY - startY;
            updateTransform();
            startX = newX;
            startY = newY;
        }
    });

    mapField.addEventListener('touchend', () => {
        isDragging = false;
    });

    mapField.addEventListener('mouseleave', function () {
        isDragging = false;
        if (zoomInCount > 0) mapField.style.cursor = 'grab';
    });
});
